function validate([n, k, row, column]) {
  if (!Number.isInteger(n) || n < 1 || n > 25) return 'n is between 1 and 25.';
  if (!Number.isInteger(k) || k < 0 || k > 100) return 'k is between 0 and 100.';
  if (!Number.isInteger(row) || row < 0 || row >= n) return 'row must be a cell of the board (0 to n - 1).';
  if (!Number.isInteger(column) || column < 0 || column >= n) return 'column must be a cell of the board (0 to n - 1).';
  return null;
}

