function knightProbability(n, k, row, column) {
  // Top-down: the chance of surviving `left` more moves from (r, c) is the average over the eight jumps.
  const memo = new Map();
  const survive = (r, c, left) => {
    if (r < 0 || c < 0 || r >= n || c >= n) return 0;
    if (left === 0) return 1;
    const key = r * 10000 + c * 100 + left;
    if (memo.has(key)) return memo.get(key);
    let sum = 0;
    for (const [a, b] of [[1, 2], [2, 1]])
      for (const sa of [1, -1])
        for (const sb of [1, -1]) sum += survive(r + sa * a, c + sb * b, left - 1);
    memo.set(key, sum / 8);
    return sum / 8;
  };
  return survive(row, column, k);
}

