function generate(rand, size) {
  const n = size === 'large' ? 20 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 6);
  const k = size === 'large' ? 50 + Math.floor(rand() * 51) : Math.floor(rand() * 6);
  return [n, k, Math.floor(rand() * n), Math.floor(rand() * n)];
}
